/* @lc app=leetcode id=2958 lang=kotlin */ class Solution { fun maxSubarrayLength(nums: IntArray, k: Int): Int = mutableMapOf<Int, Int>().let { map -> nums.indices.fold(0 to 0) { (l, maxLen), r -> map.also { it[nums[r]] = (it[nums[r]] ?: 0) + 1 }.let { generateSequence(l) { curL -> if ((map[nums[r]] ?: 0) > k) curL.also { map[nums[it]] = map[nums[it]]!! - 1 } + 1 else null }.last().let { newL -> newL to maxOf(maxLen, r - newL + 1) } } }.second } }